const slideVariants = {
    enter: (direction: number) => ({ x: direction > 0 ? "100%" : "-100%", opacity: 0 }),
    center: { x: 0, opacity: 1 },
    exit: (direction: number) => ({ x: direction > 0 ? "-100%" : "100%", opacity: 0 }),
};

const AdPopup = () => {
    const [open, setOpen] = useState(false);
    const [[index, direction], setSlide] = useState<[number, number]>([0, 0]);
    const [paused, setPaused] = useState(false);

    // The adverts stay on every page: no close button, no dismissal
    useEffect(() => {
        const timer = window.setTimeout(() => setOpen(true), SHOW_DELAY_MS);
        return () => window.clearTimeout(timer);
    }, []);

    const paginate = useCallback((step: number) => {
        setSlide(([current]) => [(current + step + ADVERTS.length) % ADVERTS.length, step]);
    }, []);

    useEffect(() => {
        if (!open || paused) return;
        const timer = window.setInterval(() => paginate(1), AUTO_ADVANCE_MS);
        return () => window.clearInterval(timer);
    }, [open, paused, paginate]);

    const handleDragEnd = (_: unknown, info: PanInfo) => {
        if (info.offset.x < -SWIPE_THRESHOLD) paginate(1);
        else if (info.offset.x > SWIPE_THRESHOLD) paginate(-1);
    };

    const ad = ADVERTS[index];

    return (
        <AnimatePresence>
            {open && (
                <motion.aside
                    role="region"
                    aria-label="Partner adverts"
                    aria-roledescription="carousel"
                    initial={{ opacity: 0, y: 40, scale: 0.96 }}
                    animate={{ opacity: 1, y: 0, scale: 1 }}
                    exit={{ opacity: 0, y: 24, scale: 0.96 }}
                    transition={{ type: "spring", stiffness: 260, damping: 24 }}
                    onMouseEnter={() => setPaused(true)}
                    onMouseLeave={() => setPaused(false)}
                    className="fixed bottom-4 right-4 left-4 sm:left-auto sm:bottom-6 sm:right-6 z-50 sm:w-[360px] overflow-hidden rounded-2xl bg-black text-white shadow-[0_20px_60px_rgba(20,20,20,0.35)] ring-1 ring-white/10"
                >
                    <div className="relative overflow-hidden">
                        <AnimatePresence initial={false} custom={direction} mode="popLayout">
                            <motion.div
                                key={ad.id}
                                custom={direction}
                                variants={slideVariants}
                                initial="enter"
                                animate="center"
                                exit="exit"
                                transition={{ x: { type: "spring", stiffness: 300, damping: 32 }, opacity: { duration: 0.2 } }}
                                drag="x"
                                dragConstraints={{ left: 0, right: 0 }}
                                dragElastic={0.6}
                                onDragEnd={handleDragEnd}
                                className="relative h-[300px] sm:h-[460px] cursor-grab touch-pan-y active:cursor-grabbing"
                                aria-roledescription="slide"
                                aria-label={`${index + 1} of ${ADVERTS.length}`}
                            >
                                <img
                                    src={ad.image}
                                    alt=""
                                    draggable={false}
                                    className="pointer-events-none absolute inset-0 h-full w-full object-cover object-[center_15%] sm:object-center"
                                />
                                <div className="absolute inset-0 bg-gradient-to-t from-black from-25% via-black/70 via-50% to-transparent to-75%" />
                                <span className="absolute left-4 top-4 rounded-full bg-primary px-3 py-1 text-xs font-medium">
                                    Sponsored
                                </span>

                                <div className="absolute inset-x-0 bottom-0 px-5 pb-11">
                                    {/* Sponsor logos stay blurred until partnerships are announced */}
                                    <div className="mb-3 flex items-center gap-3">
                                        <span className="block select-none text-white blur-[6px]" aria-hidden="true">{ad.logo}</span>
                                        <span className="rounded-full bg-white/15 px-3 py-1 text-xs font-medium text-white backdrop-blur">
                                            Announced soon
                                        </span>
                                    </div>
                                    <h3 className="text-lg sm:text-xl font-semibold leading-tight tracking-tight">
                                        {ad.title}
                                    </h3>
                                    <p className="mt-2 hidden text-sm text-white/75 sm:block">{ad.body}</p>
                                    {/* Brand links (ad.cta / ad.href) switch on once sponsors are announced */}
                                    <Button type="button" disabled className="mt-3 w-full sm:mt-4 disabled:opacity-80">
                                        Announced soon
                                    </Button>
                                </div>
                            </motion.div>
                        </AnimatePresence>
                    </div>

                    <div className="absolute inset-x-0 bottom-4 z-10 flex justify-center gap-2">
                        {ADVERTS.map((item, i) => (
                            <button
                                key={item.id}
                                type="button"
                                onClick={() => setSlide([i, i > index ? 1 : -1])}
                                aria-label={`Show advert ${i + 1}`}
                                aria-current={i === index}
                                className={cn(
                                    "h-1.5 rounded-full transition-all",
                                    i === index ? "w-6 bg-primary" : "w-1.5 bg-white/40 hover:bg-white/70",
                                )}
                            />
                        ))}
                    </div>
                </motion.aside>
            )}
        </AnimatePresence>
    );
};

export default AdPopup;
